mapper.select:
/* selectReqList - Lee MS */ A.WLFAR_CNTER_NO AS WLFAR_CNTER_NO, /* 복지센터코드 */ A.INST_NM AS WLFAR_INST_NM, /* 복지센터명 */ C.INST_NO AS INST_NO, /* 기관코드 */ C.INST_NM AS INST_NM, /* 기관명 */ C.INST_TYPE_SE_CD AS INST_TYPE_SE_CD, /* 기관유형구분코드 */ C.CTPV_CD AS CTPV_CD /* 시도코드 */ FROM ACA280 A, ACA281 B, SAA000 C WHERE A.WLFAR_CNTER_NO = B.WLFAR_CNTER_NO(+) AND B.INST_NO = C.INST_NO(+) AND A.INST_NM(+) LIKE #{INST_NM}||'%'
AND C.INST_TYPE_SE_CD = #{INST_TYPE_SE_CD}
AND C.CTPV_CD = #{CTPV_CD}
ORDER BY A.WLFAR_CNTER_NO

/* selectReqById - Lee MS */
SELECT A.WLFAR_CNTER_NO AS WLFAR_CNTER_NO, /* 복지센터번호 */ A.INST_NM AS WLFAR_INST_NM, /* 기관명 */ A.CTPV_NM AS CTPV_NM, /* 시도명 */ A.WLFAR_CNTER_TELNO AS WLFAR_CNTER_TELNO, /* 복지센터전화번호 */ A.WLFAR_CNTER_FXNO AS WLFAR_CNTER_FXNO, /* 복지센터팩스번호 */ A.INST_ADDR AS INST_ADDR, /* 기관주소 */ A.HPGE_ADDR AS HPGE_ADDR, /* 홈페이지주소 */
C.INST_NO AS INST_NO, /* 기관번호 */ C.INST_NM AS INST_NM, /* 기관명 */ C.SGG_CD AS SGG_CD, /* 시군구코드 */ C.RPRS_TELNO AS RPRS_TELNO, /* 대표전화번호 */ C.RPRS_FXNO AS RPRS_FXNO, /* 대표팩스번호 */ C.HPGE_URL_ADDR AS HPGE_URL_ADDR, /* 홈페이지URL주소 */ C.BPLC_PST_ADDR || ' ' || C.BPLC_DADDR AS INST_DADDR /* 기관주소 */ FROM ACA280 A, ACA281 B, SAA000 C /* 복지센터정보, 복지센터정보매핑, 통합기관코드 */ WHERE A.WLFAR_CNTER_NO = B.WLFAR_CNTER_NO(+) AND B.INST_NO = C.INST_NO(+) AND A.WLFAR_CNTER_NO = #{WLFAR_CNTER_NO}

mapper.delete:

 /* deleteData - Lee  MS */

DELETE FROM ACA281 /* 복지센터정보매핑 */
WHERE WLFAR_CNTER_NO = #{WLFAR_CNTER_NO}
